    ur = {i for i, row in enumerate(grid) if len(set(row)) == 1 and (include_zero or row[0] != 0)}
    uc = {j for j in range(len(grid[0])) if len({r[j] for r in grid}) == 1 and (include_zero or grid[0][j] != 0)}
    return ur, uc


def is_solid_rect(reg):
