from lib import complete_pass_by_shift, wave_fill_right

def transform(grid, fill=1):
    """Zigzag wave completion: if a truncated pass is a shifted copy of a complete pass, complete it along the wave; otherwise fill firing rows to the right edge."""
    done = complete_pass_by_shift(grid, fill=fill)
    if done is not None:
        return done
    return wave_fill_right(grid, fill=fill)
